    /// <summary>
    /// Changes the order of chat folders
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ReorderChatFoldersAsync(int[] chatFolderIds = default, int mainChatListPosition = default)
    {

           using var activity =  StartCallActivity("ReorderChatFoldersAsync", typeof(ReorderChatFolders).FullName ?? "ReorderChatFoldersAsync");

           try
           {
             return client.ReorderChatFoldersAsync(chatFolderIds, mainChatListPosition);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
